"  formatMarkdown(str) {
    if (!str) return "";
    let s = String(str);
    // Convert markdown bold: **text** -> <strong>text</strong>
    s = s.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
    // Convert markdown inline code: `code` -> <code>code</code>
    s = s.replace(/`([^`]+)`/g, "<code>$1</code>");
    // Convert newlines to linebreaks
    s = s.replace(/\r?\n/g, "<br>");
    return s;
  }"

