"/* Pattern Tab Styling */
.pattern-hero-card {
  background: linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 100%);
  border: 1px solid #bbf7d0;
  border-radius: var(--radius-lg, 10px);
  padding: 16px;
  margin-bottom: 18px;
}

.pattern-badge {
  background: #15803d;
  color: white;
  padding: 3px 9px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  display: inline-block;
}

.pattern-title-lg {
  font-size: 20px;
  font-weight: 700;
  color: #166534;
  margin: 8px 0 4px;
}

.pattern-desc-lead {
  font-size: 15px;
  color: #14532d;
  margin: 0;
  line-height: 1.5;
}

.pattern-grid-2col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 18px;
}

@media (max-width: 640px) {
  .pattern-grid-2col {
    grid-template-columns: 1fr;
  }
}

.pattern-subcard {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: var(--radius-md, 6px);
  padding: 12px 14px;
}

.pattern-subcard h4 {
  font-size: 14.5px;
  font-weight: 700;
  margin: 0 0 6px 0;
  color: #1e293b;
}

.pattern-subcard p {
  font-size: 14px;
  color: #475569;
  margin: 0;
  line-height: 1.5;
}

.pattern-steps-list {
  counter-reset: pstep;
  padding-left: 0;
  list-style: none;
  margin: 0;
}

.pattern-steps-list li {
  position: relative;
  padding-left: 32px;
  margin-bottom: 10px;
  font-size: 15px;
  color: #334155;
  line-height: 1.5;
}

