".storage-health-tag {
  background: #f1f5f9;
  color: #475569;
  font-size: 13px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 6px;
  border: 1px solid #cbd5e1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.btn-header-storage {
  background: #eff6ff;
  border: 1px solid #93c5fd;
  color: #1d4ed8;
  font-size: 13.5px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
}

.btn-header-storage:hover {
  background: #2563eb;
  color: white;
  border-color: #2563eb;
}

/* Storage Modal Layout */
.storage-modal-card {
  max-width: 860px;
  width: 95%;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
}

.storage-modal-body {
  overflow-y: auto;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Local Storage Transparency Notice Banner */
.storage-notice-banner {
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border: 1px solid #bfdbfe;
  border-left: 4px solid #2563eb;
  border-radius: var(--radius-md, 8px);
  padding: 14px 18px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.storage-notice-banner .notice-icon {
  font-size: 22px;
  flex-shrink: 0;
  margin-top: 1px;
}

.storage-notice-banner .notice-content {
  font-size: 14.5px;
  line-height: 1.5;
  color: #1e3a8a;
}

.storage-notice-banner .notice-content strong {
  display: block;
  font-size: 15px;
  margin-bottom: 3px;
  color: #1e40af;
}

.storage-notice-banner .notice-content p {
  margin: 0;
  color: #334155;
}

/* Section Headings */
.storage-section-title {
  font-size: 16px;
  font-weight: 700;
  color: #1e293b;
  margin: 0 0 12px 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Live Storage Stats Grid */
.storage-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
}


